'use client';
import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useTween } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Seg, useGrow } from '../lib/motion';
import '../designme.css';
import './set-limit.css';

/** What happens when spending reaches the cap */
export type SetLimitMode = 'pause' | 'ask' | 'keep';

export interface SetLimitMessage {
  /** True when the forecast goes past the cap */
  over: boolean;
  cap: number;
  /** The cap minus the forecast, what is left at the end of the period */
  left: number;
  mode: SetLimitMode;
}

export interface SetLimitProps {
  /** The cap. Leave it out to let the slider set it */
  value?: number;
  defaultValue?: number;
  onValueChange?: (cap: number) => void;
  /** The lowest cap the slider allows */
  min?: number;
  /** The highest cap the slider allows */
  max?: number;
  /** How far one arrow key press or slider notch moves the cap */
  step?: number;
  /** Spent so far this period, the solid part of the bar */
  spent?: number;
  /** Where spending is headed by the end of the period, the striped part of the bar */
  forecast?: number;
  /** What happens at the cap. Leave it out to let the switch set it */
  mode?: SetLimitMode;
  defaultMode?: SetLimitMode;
  onModeChange?: (mode: SetLimitMode) => void;
  title?: string;
  /** The quiet line under the title, like "Resets Nov 1" */
  subtitle?: string;
  /** When the forecast passes the cap, like "Oct 27" */
  passesOn?: string;
  /** Writes an amount, like "$200" */
  format?: (n: number) => string;
  /** The word in front of the cap, "Cap" by default */
  capLabel?: string;
  /** Shows the cap as a small field the person can type in (the default). Enter or leaving the field keeps it, held to min and max; Escape goes back */
  editable?: boolean;
  /** Replaces the line under the bar, which by default warns when the forecast passes the cap */
  message?: (state: SetLimitMessage) => ReactNode;
  className?: string;
}

const MODES: { value: SetLimitMode; label: string }[] = [{ value: 'pause', label: 'Pause runs' }, { value: 'ask', label: 'Ask me' }, { value: 'keep', label: 'Keep going' }];
const WILL: Record<SetLimitMode, string> = { pause: 'pause', ask: 'wait for you', keep: 'keep going' };

/** A spending cap on a bar that shows what is spent and what is forecast, with what to do at the limit. */
export function SetLimit({ value, defaultValue = 200, onValueChange, min = 50, max = 500, step = 10, spent = 128, forecast = 184, mode, defaultMode = 'pause', onModeChange,
  title = 'Monthly agent budget', subtitle = 'Resets Nov 1', passesOn = 'Oct 27', format = n => '$' + n, capLabel = 'Cap', editable = true, message, className }: SetLimitProps) {
  const [capRaw, setCap] = useControllable(value, defaultValue, onValueChange);
  const [atLimit, setMode] = useControllable(mode, defaultMode, onModeChange);
  const cap = Math.max(min, Math.min(max, capRaw));
  const [drag, setDrag] = useState(false);
  // the bars fill in a moment after the card appears
  const [ready, setReady] = useState(false);
  useEffect(() => { const t = setTimeout(() => setReady(true), 200); return () => clearTimeout(t); }, []);
  const bar = useRef<HTMLDivElement>(null);
  const [outer, inner] = useGrow();
  // the knob and bars glide to a new cap, except while it is being dragged
  const shown = useTween(cap, drag ? 1 : 450);
  // the figure being typed, while the field has focus
  const [draft, setDraft] = useState<string | null>(null);
  const before = useRef(cap), cancel = useRef(false);
  const input = useRef<HTMLInputElement>(null);
  const clamp = (n: number) => Math.max(min, Math.min(max, Math.round(n)));
  const commit = () => {
    if (draft === null) return;
    const n = cancel.current || draft === '' ? before.current : clamp(parseInt(draft, 10));
    setCap(n); cancel.current = false; setDraft(null);
  };
  // the symbols around the number in `format`, like the "$" in "$200", stay put while the number is typed
  const text = format(cap), first = text.search(/\d/), last = text.length - [...text].reverse().join('').search(/\d/);
  const pre = first < 0 ? '' : text.slice(0, first), post = first < 0 ? '' : text.slice(last);

  const pct = (x: number) => (x - min) / (max - min) * 100;
  const snap = (x: number) => Math.max(min, Math.min(max, Math.round(x / step) * step));
  const at = (e: PointerEvent) => { const b = bar.current!.getBoundingClientRect(); setCap(snap(min + (max - min) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width)))); };
  const key = (e: KeyboardEvent) => {
    const dir = ({ ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 } as Record<string, number>)[e.key]; if (!dir) return;
    e.preventDefault(); setCap(Math.max(min, Math.min(max, cap + dir * step)));
  };

  const over = forecast > cap, left = cap - forecast;
  const used = ready ? Math.min(100, spent / shown * pct(shown)) : 0;
  const fc = ready ? Math.min(pct(shown), forecast / shown * pct(shown)) : 0;
  const figure = draft ?? String(Math.round(shown));
  const line = message ? message({ over, cap, left, mode: atLimit })
    : over ? <span>Forecast passes your cap around {passesOn}. Runs will {WILL[atLimit]}.</span>
      : <span>On track. About {format(left)} left at month end.</span>;

  return (
    // the panel grows and shrinks with the line under the bar, staying centred where it is centred
    <div data-dm="" ref={outer} className={cx('dm-slx dm-panel dm-growing', className)}><div ref={inner} className="dm-grow">
      <div className="dm-slx-h">
        <div><b>{title}</b>{subtitle && <span className="dm-muted">{subtitle}</span>}</div>
        {/* the cap is labelled and, when it can change, is a small field with the currency in front (a click selects it all,
            so typing replaces it) */}
        <span className="dm-slx-cap"><span className="dm-muted" aria-hidden="true">{capLabel}</span>
        {editable ? (
          <label className="dm-num dm-slx-v" onPointerDown={e => { if (document.activeElement !== input.current) { e.preventDefault(); input.current?.focus(); } }}>
            {pre && <span className="dm-cur">{pre}</span>}<input ref={input} className="dm-slx-in" inputMode="numeric" autoComplete="off" aria-label={`${title}, ${capLabel.toLowerCase()}`} value={figure} style={{ width: Math.max(1, figure.length) + 'ch' }}
              onFocus={e => { before.current = cap; setDraft(String(cap)); e.currentTarget.select(); }}
              onChange={e => { const v = e.target.value.replace(/\D/g, '').slice(0, 6); setDraft(v); const n = +v; if (v && n >= min && n <= max) setCap(n); }}
              onKeyDown={e => {
                if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur(); }
                else if (e.key === 'Escape') { cancel.current = true; e.currentTarget.blur(); }
                else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') { e.preventDefault(); const n = clamp((parseInt(draft ?? '', 10) || cap) + (e.key === 'ArrowUp' ? step : -step)); setDraft(String(n)); setCap(n); }
              }}
              onBlur={commit} />{post}
          </label>
        ) : <b className="dm-num dm-slx-v">{format(cap)}</b>}
        </span>
      </div>
      <div ref={bar} className="dm-slx-bar"
        onPointerDown={e => { e.currentTarget.setPointerCapture(e.pointerId); setDrag(true); at(e); }}
        onPointerMove={e => { if (drag) at(e); }}
        onPointerUp={() => setDrag(false)} onPointerCancel={() => setDrag(false)}>
        <div className="dm-slx-used" style={{ width: used + '%' }} />
        <div className="dm-slx-fc" style={{ width: fc + '%' }} />
        {/* the cap it sets is the figure in the head, so the knob carries no amount of its own */}
        <button type="button" className={cx('dm-slx-k', drag && 'dm-drag')} role="slider" aria-label="Budget cap"
          aria-valuemin={min} aria-valuemax={max} aria-valuenow={cap} aria-valuetext={format(cap)} style={{ left: pct(shown) + '%' }} onKeyDown={key} />
      </div>
      <div className="dm-slx-lg dm-muted">
        <span><i style={{ background: 'var(--dm-accent-mark,var(--dm-accent))' }} />Spent <b className="dm-num">{format(spent)}</b></span>
        <span><i className="dm-fc" />Forecast <b className="dm-num">{format(forecast)}</b></span>
      </div>
      <div className="dm-slx-warn" aria-live="polite">
        {/* the line comes in again when it changes between on track and over, or the choice at the limit changes */}
        {/* on track: a neutral line with the green tick; over: a warning notice, a faint warning tint, the filled warning sign and
            the words in the text colour */}
        {ready && <span key={String(over) + atLimit} className={cx(over ? 'dm-w' : 'dm-o', 'dm-enter')}>
          {over ? <svg className="dm-slx-wi" viewBox="0 0 24 24" aria-hidden="true"><path className="dm-a" d="M12 3.6 2.6 19.9h18.8z" /><path className="dm-b" d="M12 9.6v4.4M12 17v.01" /></svg> : <Icon name="ok" size="xs" />}{line}
        </span>}
      </div>
      <div className="dm-slx-opt">
        <span className="dm-muted">At the limit</span>
        <Seg className="dm-slx-sg" label="At the limit" value={atLimit} onChange={setMode} options={MODES} />
      </div>
    </div></div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Set limit ---------- */
.dm-slx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:14px;container:slx/inline-size}
/* the budget figure shares the title's line: the two sit on one baseline */
.dm-slx-h{display:flex;align-items:first baseline;justify-content:space-between}
.dm-slx-h>div{display:flex;flex-direction:column;font-size:14px}
.dm-slx-h b{font-weight:500}
.dm-slx-h .dm-muted{font-size:12px}
/* the cap is labelled and reads as a field at rest (owner, 28 Nov): "Cap" in the muted text, then a small field with its $ in
   front, white with the dimmed field edge, which steps up one grey while you type. A cap you can't change is the figure alone */
.dm-slx-cap{display:inline-flex;align-items:baseline;gap:var(--dm-s-2)}
.dm-slx-v{display:inline-flex;align-items:baseline;font-size:14px;font-weight:500!important;letter-spacing:-.02em;padding:3px var(--dm-s-2);border-radius:var(--dm-r-field);cursor:text;transition:box-shadow .2s var(--dm-ease)}
.dm-slx-v:has(input){background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
.dm-slx-v:has(input):focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-slx-v .dm-cur{color:var(--dm-muted);font-weight:400;margin-right:2px}
@supports (corner-shape:squircle){.dm-slx-v{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-slx-in{width:3ch;min-width:1ch;padding:0;margin:0;border:0;background:none;font:inherit;font-variant-numeric:tabular-nums;letter-spacing:inherit;color:inherit;text-align:right;outline:none;caret-color:var(--dm-accent-fg,var(--dm-accent))}
/* the bar, with the same room above and below its knob. The cap it sets is the figure in the head, so the knob carries no
   amount of its own over it */
.dm-slx-bar{position:relative;height:12px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-chip);margin:var(--dm-s-2) 0;touch-action:none;cursor:pointer}
.dm-slx-used{position:absolute;left:0;top:0;bottom:0;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-accent-mark,var(--dm-accent));transition:width .8s var(--dm-ease);z-index:1}
/* the forecast: stripes of the accent, and the legend's swatch is the same stripes */
.dm-slx{--dm-slx-hatch:repeating-linear-gradient(-45deg,color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent) 0 3px,color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 18%,transparent) 3px 6px)}
.dm-slx-fc{position:absolute;left:0;top:0;bottom:0;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-slx-hatch);transition:width .8s var(--dm-ease)}
/* the knob: ink, with a quiet grey ring while it is pointed at or dragged (a highlight is never a coloured glow) */
.dm-slx-k{position:absolute;top:50%;width:6px;height:26px;margin:-13px 0 0 -3px;border-radius:var(--dm-r-pill);background:var(--dm-fg);z-index:2;cursor:grab;transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
.dm-slx-k.dm-drag{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 12%,transparent)}
@media (hover:hover) and (pointer:fine){.dm-slx-k:hover{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 12%,transparent)}}
.dm-slx-k.dm-drag{cursor:grabbing}
.dm-slx-lg{display:flex;gap:var(--dm-s-4);font-size:12px}
.dm-slx-lg span{display:flex;align-items:center;gap:6px}
.dm-slx-lg b{color:var(--dm-fg);font-weight:500}
.dm-slx-lg i{width:8px;height:8px;border-radius:var(--dm-r-tiny,3px)}
.dm-slx-lg i.dm-fc{background:var(--dm-slx-hatch)}
/* the line under the bar. On track: a neutral line with the green tick. Over: a warning notice (owner, 18 Nov), a faint
   warning tint as wide as the content, the filled warning sign in the warning mark, and the words in the text colour */
.dm-slx-warn{font-size:12.5px;line-height:18px;min-height:18px}
.dm-slx-warn .dm-o{display:flex;align-items:center;gap:var(--dm-s-2);color:var(--dm-fg2)}
.dm-slx-warn .dm-o svg{flex:none;color:var(--dm-ok-mark)}
.dm-slx-warn .dm-w{display:grid;grid-template-columns:16px minmax(0,1fr);align-items:start;gap:var(--dm-s-2);padding:var(--dm-s-2) 10px;text-wrap:pretty;border-radius:var(--dm-r-in);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent);color:var(--dm-fg)}
.dm-slx-wi{width:16px;height:16px;margin-top:1px;overflow:visible}
.dm-slx-wi .dm-a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.dm-slx-wi .dm-b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.dm-slx-opt{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12.5px}
.dm-slx-sg button{font-size:12px;height:28px;padding:0 10px}
/* narrow: the choice under its label, as wide as the bar, its three options sharing it */
@container slx (max-width:360px){
  .dm-slx-opt{flex-direction:column;align-items:stretch;gap:var(--dm-s-2)}
  .dm-slx-sg{display:flex}
  .dm-slx-sg button{flex:1;padding:0 6px}
}
:root:not([data-style="soft"],[data-style="clean"]) .dm-slx-warn .dm-w:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
/* Clean (owner, 17 and 20 Nov): its content 16px from each edge; the bar has Clean's soft inner shadow, as Slider's rail does */
:root[data-style="clean"] .dm-slx.dm-panel,:root [data-style="clean"] .dm-slx.dm-panel,:root [data-style="clean"].dm-slx.dm-panel{padding:16px}
:root[data-style="clean"] .dm-slx-bar,:root [data-style="clean"] .dm-slx-bar,:root [data-style="clean"].dm-slx-bar{box-shadow:var(--dm-track-ring)}
